update public.learning_paths
set
  title = 'Political Philosophy',
  goal = 'Political Philosophy',
  summary = 'Students explain major theories of authority, legitimacy, liberty, equality, rights, democracy, punishment, property, and global justice, reconstruct and evaluate arguments from classical, modern, and contemporary political philosophy, and compare liberal, libertarian, republican, socialist, feminist, critical, and multicultural approaches to political life. They apply normative concepts to law, public policy, institutions, human rights, migration, war, climate, and democratic practice, use evidence and institutional context without confusing empirical description with normative justification, and produce a policy-focused philosophical argument.',
  data = $pphiljson${"slug": "political-philosophy", "title": "Political Philosophy", "description": "Students explain major theories of authority, legitimacy, liberty, equality, rights, democracy, punishment, property, and global justice, reconstruct and evaluate arguments from classical, modern, and contemporary political philosophy, and compare liberal, libertarian, republican, socialist, feminist, critical, and multicultural approaches to political life. They apply normative concepts to law, public policy, institutions, human rights, migration, war, climate, and democratic practice, use evidence and institutional context without confusing empirical description with normative justification, and produce a policy-focused philosophical argument.", "topics": [{"id": "f35c6377-aaf5-40dc-9a62-e67db4576c39", "type": "topic", "title": "Political Philosophy as Normative Inquiry: Power, Justice, and Public Reason", "description": "Establish political philosophy as the disciplined evaluation of authority, institutions, rights, duties, and public life.", "children": [{"id": "8c9d2d9f-0a6b-4abc-b078-9779b23ef762", "type": "subtopic", "title": "Normative political questions", "children": [{"id": "d7ca3fdc-45cd-4fbd-b59f-5477eaac08fd", "type": "concept", "title": "Justice"}, {"id": "01b3ce66-60ec-482b-a624-9d4997fc5d80", "type": "concept", "title": "Legitimacy"}, {"id": "cd41a6d1-24d0-4588-94cf-a1958e1f39e5", "type": "concept", "title": "Authority"}, {"id": "d44d16d8-be5b-4775-9490-711d16d53629", "type": "concept", "title": "Rights and duties"}], "description": "Why it matters: The point is to distinguish what political institutions are from whether they are justified."}, {"id": "28edfd11-35cc-49a9-817c-8eea46d6a8a4", "type": "subtopic", "title": "Public reason and justification", "children": [{"id": "b42a16a5-2813-45f0-9243-ecc96255c86a", "type": "concept", "title": "Reason-giving"}, {"id": "eecbcd6c-b36a-40a9-b1d4-e3cf1b23a4fc", "type": "concept", "title": "Reciprocity"}, {"id": "57cd640c-edc9-4e88-bc7e-74fc2ba39611", "type": "concept", "title": "Reasonable disagreement"}, {"id": "c9ef959e-bcc1-4190-8622-e101aef6b219", "type": "concept", "title": "Public justification"}], "description": "Why it matters: Political claims must be justified to others who may not share the same worldview."}, {"id": "a0fc95be-e3c3-4668-b61b-7feb81429e3b", "type": "subtopic", "title": "Methods of political philosophy", "children": [{"id": "485706a2-f61f-44ae-afc6-48de6ec6128d", "type": "concept", "title": "Conceptual analysis"}, {"id": "9641b0d6-662a-47d7-ba7c-2b6a2cf90b76", "type": "concept", "title": "Reflective equilibrium"}, {"id": "532b882e-07bb-4783-8357-6eb4f22e00a0", "type": "concept", "title": "Thought experiments"}, {"id": "99fd001d-e785-4d38-8699-994a127548cc", "type": "concept", "title": "Institutional realism"}], "description": "Why it matters: Students learn how political philosophers use argument, cases, history, institutions, and moral theory together."}]}, {"id": "7cba1d53-3af6-4cfa-a564-1990ee26c28c", "type": "topic", "title": "Ancient Political Thought: Plato, Aristotle, Citizenship, and the Good Life", "description": "Study foundational accounts of justice, virtue, education, regime types, and civic membership.", "children": [{"id": "d8835c2a-a31c-45de-8c8d-65075db6db83", "type": "subtopic", "title": "Plato and justice", "children": [{"id": "72714677-0130-4dc4-b2fb-75b9f9e6c52c", "type": "concept", "title": "The Republic"}, {"id": "ab0da092-889d-41c8-aba4-68a6e770df09", "type": "concept", "title": "Philosopher-rulers"}, {"id": "aa2c6216-895e-4ce9-8b7c-d74e3d97d630", "type": "concept", "title": "Justice as harmony"}, {"id": "9406d579-4e27-4460-8096-7a962b0b1d9a", "type": "concept", "title": "Critiques of democracy"}], "description": "Why it matters: Plato frames political order around justice, education, knowledge, and the health of the soul and city."}, {"id": "322058d8-096b-4c05-a764-bd280bf92df1", "type": "subtopic", "title": "Aristotle and the polis", "children": [{"id": "e064eb80-54de-4ccd-8588-4bcef541c528", "type": "concept", "title": "Human beings as political animals"}, {"id": "3f710e27-f4b3-4a9d-bb29-7f7995261c83", "type": "concept", "title": "Virtue and habituation"}, {"id": "f52fe1f1-1008-4a91-a566-3a350cc19400", "type": "concept", "title": "Citizenship"}, {"id": "0f5059c2-b44c-4d0d-b8c6-9a6d33f96633", "type": "concept", "title": "Mixed regimes"}], "description": "Why it matters: Aristotle connects politics to human flourishing, virtue, citizenship, and constitutional forms."}, {"id": "a4ba9632-3c4d-45e2-a398-47d8751b7cf4", "type": "subtopic", "title": "Ancient legacies", "children": [{"id": "383d8fb6-5b07-469f-8a49-3913d9e2cdce", "type": "concept", "title": "Exclusion"}, {"id": "42d02df7-9708-47de-940a-4427f47d0d91", "type": "concept", "title": "Civic virtue"}, {"id": "b3172703-cc57-4706-b18c-72e4943fe04d", "type": "concept", "title": "Common good"}, {"id": "b55238d2-24fe-4286-8cd0-58d2934ebe8e", "type": "concept", "title": "Regime classification"}], "description": "Why it matters: Ancient texts introduce questions about elitism, civic education, slavery, gender, and who counts as a political member."}]}, {"id": "2b1b7cf0-a2eb-42a3-90b0-9f117cf7c315", "type": "topic", "title": "Authority, Legitimacy, Obligation, and Consent", "description": "Ask when political power is justified and why, if ever, citizens have duties to obey.", "children": [{"id": "1c7949bb-9ae3-4208-abca-c01de003e04c", "type": "subtopic", "title": "Political authority", "children": [{"id": "cac43e7a-b9e1-4a3b-9e6d-883633c5f565", "type": "concept", "title": "De facto versus de jure authority"}, {"id": "e11690d7-c47e-42c4-93ec-3740d203d1f0", "type": "concept", "title": "Commands"}, {"id": "e205e150-5385-4073-a484-a960aa5e1240", "type": "concept", "title": "Legitimate rule"}, {"id": "7faecbca-1f67-49d8-9c0b-cc27152c1c2e", "type": "concept", "title": "Anarchist challenges"}], "description": "Why it matters: Authority asks whether the state has a right to rule, not merely the power to coerce."}, {"id": "3cf005da-bf75-4487-8166-a686533d9a9c", "type": "subtopic", "title": "Political obligation", "children": [{"id": "436d767d-d783-4f51-8aa7-1011096cd470", "type": "concept", "title": "Consent"}, {"id": "9caef406-16aa-4cb4-844e-18ede8c163a8", "type": "concept", "title": "Fair play"}, {"id": "a4a09d6c-47d5-4d9c-a311-fac6cecdbb9c", "type": "concept", "title": "Gratitude"}, {"id": "4b759b3f-0997-437b-8d3c-77be0ca49676", "type": "concept", "title": "Natural duty"}], "description": "Why it matters: Students evaluate why people might be morally bound to obey law."}, {"id": "1c43e731-dac0-4a0b-aa86-3b6255e66a01", "type": "subtopic", "title": "Legitimacy under disagreement", "children": [{"id": "a6cfe4e9-e31d-4eb3-a778-7f1a502ab7cc", "type": "concept", "title": "Procedural legitimacy"}, {"id": "1c63911e-e2f1-4b85-8815-037b5b084ffd", "type": "concept", "title": "Substantive legitimacy"}, {"id": "ddf2df22-3b25-43c1-b7ec-0593fa51694c", "type": "concept", "title": "Civil disobedience"}, {"id": "2be69d73-d18a-4cd0-9693-489ca085f1f9", "type": "concept", "title": "Conscientious refusal"}], "description": "Why it matters: Modern pluralistic societies require standards of legitimacy amid deep disagreement."}]}, {"id": "fc5200d4-fc01-47aa-bea3-06e81a083d63", "type": "topic", "title": "Social Contract Traditions: Hobbes, Locke, Rousseau, Kant, and Rawls", "description": "Trace contractarian approaches to order, consent, freedom, equality, and fair social cooperation.", "children": [{"id": "6c29978a-8356-4c72-b730-921f711d01d8", "type": "subtopic", "title": "Classical contract theories", "children": [{"id": "a8906ef1-7477-4b6f-b493-d4f26d9bc5a7", "type": "concept", "title": "State of nature"}, {"id": "b48fba8e-f5cd-4282-8757-0f94fe393593", "type": "concept", "title": "Consent"}, {"id": "4483a0ca-87ff-425c-aba1-272a4450d87e", "type": "concept", "title": "Sovereignty"}, {"id": "41fb4ede-aeec-4c6a-a32c-ad628e43844e", "type": "concept", "title": "Property and security"}], "description": "Why it matters: The social contract tradition asks what free and equal persons would accept as terms of political order."}, {"id": "c607b785-1f70-46ed-9593-43a00703e766", "type": "subtopic", "title": "Rousseau and freedom", "children": [{"id": "2635554a-4947-4f97-bf83-42cd97ee1d21", "type": "concept", "title": "General will"}, {"id": "662616d1-030b-4f87-9bda-73f7ebfc8954", "type": "concept", "title": "Moral freedom"}, {"id": "f0edce7c-579b-4afd-9d96-0cdcc14f86e1", "type": "concept", "title": "Civil religion"}, {"id": "813fa051-fefb-4f30-8c2c-13425dfcdc0c", "type": "concept", "title": "Corruption and inequality"}], "description": "Why it matters: Rousseau shifts the debate toward dependence, inequality, and collective self-rule."}, {"id": "8e4d4313-138e-4774-ba52-abfd431a5ee5", "type": "subtopic", "title": "Rawls and justice as fairness", "children": [{"id": "b086689a-9f35-4a57-b073-34b192b6eaa5", "type": "concept", "title": "Original position"}, {"id": "75a6aa25-36af-4042-b2c5-16c540563a20", "type": "concept", "title": "Veil of ignorance"}, {"id": "41090a5f-cae4-4401-ae76-727f20345f19", "type": "concept", "title": "Basic structure"}, {"id": "cf7d2867-e915-4110-9608-3a99ee7a4385", "type": "concept", "title": "Two principles of justice"}], "description": "Why it matters: Rawls updates contract theory into a method for choosing fair principles of social cooperation."}]}, {"id": "33855095-6992-4480-ad0a-125e5f3fc1ef", "type": "topic", "title": "Liberty, Coercion, Harm, Autonomy, and Paternalism", "description": "Analyze what freedom requires and when the state may restrict individual choice.", "children": [{"id": "54c98f97-bdf3-438c-bf23-e40602f0d989", "type": "subtopic", "title": "Concepts of liberty", "children": [{"id": "76687027-0528-495e-b26f-7ec40c5b01a2", "type": "concept", "title": "Negative liberty"}, {"id": "26ddc801-552f-4cb2-9725-f06ae3aa3d30", "type": "concept", "title": "Positive liberty"}, {"id": "309dcc5f-87b3-4b42-90f3-c49ccfd0badb", "type": "concept", "title": "Republican liberty"}, {"id": "fb9aa0c9-1790-4838-91af-0ffa85126bef", "type": "concept", "title": "Effective freedom"}], "description": "Why it matters: Students learn that freedom can mean noninterference, self-mastery, non-domination, or real capability."}, {"id": "e7696901-8efb-4ce7-94a2-80f9372622d1", "type": "subtopic", "title": "Harm and coercion", "children": [{"id": "6245750e-d847-49b1-bb6b-6f204fe56e26", "type": "concept", "title": "Mill's harm principle"}, {"id": "5b8466ce-2f1c-44e8-9a94-95268b491296", "type": "concept", "title": "Offense"}, {"id": "9114e98d-519d-4cd8-b4d1-f6829f03c5b8", "type": "concept", "title": "Self-regarding conduct"}, {"id": "9ace74d4-86d1-4255-8197-20fc9cba6b92", "type": "concept", "title": "Coercive law"}], "description": "Why it matters: The harm principle frames when coercion may be justified to protect others."}, {"id": "820bbea4-0a76-4418-ac0d-8f6ba1fc3269", "type": "subtopic", "title": "Paternalism and autonomy", "children": [{"id": "9dcdb327-89eb-448b-9d12-615cf138bcb2", "type": "concept", "title": "Soft paternalism"}, {"id": "94c66789-5199-4480-b8f1-98411bd9963b", "type": "concept", "title": "Hard paternalism"}, {"id": "e62011df-52ae-49c6-a66b-56419db6ab4a", "type": "concept", "title": "Nudges"}, {"id": "8f213e8a-8f5a-4f59-9456-1610ff3adc09", "type": "concept", "title": "Autonomy and competence"}], "description": "Why it matters: Paternalism tests whether the state may restrict people for their own good."}]}, {"id": "826c4e84-1516-40fa-bafd-0c72e487e1de", "type": "topic", "title": "Equality, Distributive Justice, Welfare, Capability, and Desert", "description": "Compare theories of fair distribution, opportunity, need, merit, and human flourishing.", "children": [{"id": "14cb8741-9c81-4670-9e04-87694c460241", "type": "subtopic", "title": "Egalitarian theories", "children": [{"id": "b462b580-63a8-4306-951f-49f041c5833b", "type": "concept", "title": "Equality of opportunity"}, {"id": "f111f153-d92b-43bd-a4e3-ade72e8c4cba", "type": "concept", "title": "Luck egalitarianism"}, {"id": "8a493489-9eeb-422b-b697-a6b9991fb87e", "type": "concept", "title": "Relational equality"}, {"id": "59b86dfc-0b79-4336-b6ef-1b10be4ff096", "type": "concept", "title": "Sufficientarianism"}], "description": "Why it matters: Equality debates ask what should be equalized and why inequality matters."}, {"id": "f7903045-d491-4d6d-b369-b54ed9bc0f7a", "type": "subtopic", "title": "Distributive principles", "children": [{"id": "68c599c6-4a95-4986-8b29-d10e3aff7b36", "type": "concept", "title": "Utilitarianism"}, {"id": "c459dbff-248f-41be-8621-eb52f8b966ea", "type": "concept", "title": "Prioritarianism"}, {"id": "91268ca1-f9d8-49b4-a1a0-a9c489f21ce3", "type": "concept", "title": "Rawlsian difference principle"}, {"id": "c980cb47-a4bd-4dda-a2ec-8edfe938184c", "type": "concept", "title": "Capability approach"}], "description": "Why it matters: Students compare need, welfare, resources, capabilities, and desert as grounds for distribution."}, {"id": "93bf3654-8a33-4133-a499-d7afb16bea8a", "type": "subtopic", "title": "Institutional design", "children": [{"id": "118f4750-1e22-47b4-a002-fbdfce0f1a74", "type": "concept", "title": "Redistribution"}, {"id": "da5b35be-a90a-4907-bd47-74f23c00c53c", "type": "concept", "title": "Social insurance"}, {"id": "28e31394-fec7-4a01-8b26-74a22c097b70", "type": "concept", "title": "Public goods"}, {"id": "683b9893-3ff3-4686-9437-80262c093594", "type": "concept", "title": "Structural inequality"}], "description": "Why it matters: Justice becomes concrete through taxation, welfare, education, health, labor, and housing institutions."}]}, {"id": "ab5ffd50-5697-4593-afaf-3666a712123a", "type": "topic", "title": "Rights, Duties, Human Rights, and Constitutionalism", "description": "Study rights as moral, political, legal, and institutional claims that structure public life.", "children": [{"id": "b6caf9fe-f96f-4f18-a7c2-dc2bc51e9546", "type": "subtopic", "title": "Rights theory", "children": [{"id": "cea2897d-44fd-4f0e-b1e1-ed4ca3d4e0a1", "type": "concept", "title": "Claim rights"}, {"id": "2997980f-b203-4ee2-bc06-5df6b28b320c", "type": "concept", "title": "Liberty rights"}, {"id": "1237b1a6-ee48-47ec-8805-738c9ec30779", "type": "concept", "title": "Negative and positive rights"}, {"id": "c787e108-45a5-4c18-a0e2-cf3f761d8eb7", "type": "concept", "title": "Rights conflicts"}], "description": "Why it matters: Rights protect interests, choices, dignity, or status against certain forms of interference."}, {"id": "e1062737-1269-4190-95b6-eb63b5a99705", "type": "subtopic", "title": "Human rights", "children": [{"id": "40b897b7-3e6a-492c-b026-23c30538e010", "type": "concept", "title": "Moral human rights"}, {"id": "932fe72b-a7a7-47f0-b72f-50873e677e74", "type": "concept", "title": "Legal human rights"}, {"id": "adc9a4eb-45c3-4111-ae88-162bef37483c", "type": "concept", "title": "Treaty systems"}, {"id": "fe51ee8d-6249-40ea-918b-5151104856b2", "type": "concept", "title": "Humanitarian advocacy"}], "description": "Why it matters: Human rights raise questions about universality, enforcement, sovereignty, and cultural pluralism."}, {"id": "815ccd21-529a-4482-af0b-19cb572bc958", "type": "subtopic", "title": "Constitutionalism", "children": [{"id": "53edf965-fdaf-4e7b-bc93-ae7a6a7129c2", "type": "concept", "title": "Judicial review"}, {"id": "213dd12c-13ea-41d5-99c3-0d5756306ed4", "type": "concept", "title": "Separation of powers"}, {"id": "dec35ba7-c202-48fc-9bb8-a99e9300ff94", "type": "concept", "title": "Civil liberties"}, {"id": "d98be082-fecc-43e3-8a39-9ca39ad3a315", "type": "concept", "title": "Equal protection"}], "description": "Why it matters: Constitutional limits translate moral and political rights into institutional structure."}]}, {"id": "ab58c11b-d705-4049-9a96-914f8d71aba4", "type": "topic", "title": "Democracy, Representation, Deliberation, and Political Participation", "description": "Evaluate democracy not just as voting, but as collective self-government and public reasoning.", "children": [{"id": "ac75a9de-20fd-4324-a00d-d5d3c3e5ca7f", "type": "subtopic", "title": "Democratic justification", "children": [{"id": "601dab06-de90-4d41-b619-05d2da9b87aa", "type": "concept", "title": "Political equality"}, {"id": "ed353646-b3bb-4943-abe8-59ec26816791", "type": "concept", "title": "Majority rule"}, {"id": "5730e5aa-3dc1-494f-b2a7-049089ab9d40", "type": "concept", "title": "Epistemic democracy"}, {"id": "0c2e22e5-d389-4beb-89be-4a19b782bd00", "type": "concept", "title": "Instrumental and intrinsic defenses"}], "description": "Why it matters: Democracy can be defended through equality, autonomy, epistemic value, peace, or legitimacy."}, {"id": "8d777e56-57ed-4a14-917c-b1fc4150b758", "type": "subtopic", "title": "Representation", "children": [{"id": "fa4ab2c0-5a78-4ff4-9192-df2f597917f8", "type": "concept", "title": "Trustee model"}, {"id": "5da006d3-27ad-4038-8f15-44e1581e4f1e", "type": "concept", "title": "Delegate model"}, {"id": "f26024f2-eb04-48ce-9356-28f0e47b625f", "type": "concept", "title": "Descriptive representation"}, {"id": "231f0a88-28d6-423d-96a6-9aa7fc02f057", "type": "concept", "title": "Accountability"}], "description": "Why it matters: Representation asks who speaks for whom and under what standards of accountability."}, {"id": "b66ecca0-8d2b-4aa0-b97d-2f507794b74a", "type": "subtopic", "title": "Deliberation and participation", "children": [{"id": "6be68abe-b6c7-4fa7-b92d-4c7ef0f6f9a8", "type": "concept", "title": "Deliberative democracy"}, {"id": "7e3359e3-d118-4a21-bbe0-26233dd1eb25", "type": "concept", "title": "Public sphere"}, {"id": "66285097-5baf-4ef9-90d0-49873696ca16", "type": "concept", "title": "Participation"}, {"id": "71220d2a-e02a-41bc-b9b7-9d6e2e14b84f", "type": "concept", "title": "Civic education"}], "description": "Why it matters: Democracy improves when citizens reason together rather than merely aggregate preferences."}]}, {"id": "57b2d28a-c661-42cf-8c7d-75d057d6a5d2", "type": "topic", "title": "Law, Punishment, Policing, and the Criminal State", "description": "Examine state coercion through law, punishment, public safety, legitimacy, and justice.", "children": [{"id": "f0fa6119-90ff-40ce-87ba-1dc5b21b59e6", "type": "subtopic", "title": "The rule of law", "children": [{"id": "a175906c-fde6-4934-8955-6d90b26ec347", "type": "concept", "title": "Generality"}, {"id": "e027c8b0-0828-43b9-b555-f8aad750a7b5", "type": "concept", "title": "Publicity"}, {"id": "2cc6fd10-1898-416c-aa93-6dd3a6b144bb", "type": "concept", "title": "Due process"}, {"id": "eb4425fd-c1cb-4182-ac2e-a57bccd3c036", "type": "concept", "title": "Equality before law"}], "description": "Why it matters: The rule of law restrains arbitrary power and makes coercion publicly accountable."}, {"id": "40a2b50a-9953-4c9c-8351-eed696eda746", "type": "subtopic", "title": "Punishment theories", "children": [{"id": "b4da8707-8789-407e-9548-dfb44b251802", "type": "concept", "title": "Retributivism"}, {"id": "0f004599-7543-48f3-ae27-2ca9dcb92c0d", "type": "concept", "title": "Deterrence"}, {"id": "c985febf-b59f-41f7-8e51-4724f497790f", "type": "concept", "title": "Rehabilitation"}, {"id": "6859c782-26ec-430e-8436-f113479c2567", "type": "concept", "title": "Restorative justice"}], "description": "Why it matters: Punishment requires special justification because it intentionally imposes hardship."}, {"id": "ed1043d2-50c9-4758-a008-da4cff78f572", "type": "subtopic", "title": "Policing and legitimacy", "children": [{"id": "6b377ae7-c69c-44ab-87ad-2d091dda7ee1", "type": "concept", "title": "Use of force"}, {"id": "5f1066d8-166b-43e9-a15d-f98b46d33516", "type": "concept", "title": "Procedural justice"}, {"id": "6278990a-fb96-44ba-8aa7-9f2b40f9b8d2", "type": "concept", "title": "Mass incarceration"}, {"id": "c6fe672c-9559-43be-8401-80606cbfb18a", "type": "concept", "title": "Abolition and reform"}], "description": "W